import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"契約忠實度與演進","description":"實際 payload 驗證與獨立 producer/consumer fixture 能證明什麼，以及不能證明什麼。","frontmatter":{"title":"契約忠實度與演進","description":"實際 payload 驗證與獨立 producer/consumer fixture 能證明什麼，以及不能證明什麼。"},"headers":[],"relativePath":"zh-tw/guide/schema-conversion/contract-fidelity.md","filePath":"zh-tw/guide/schema-conversion/contract-fidelity.md","lastUpdated":1789026761000}'),a={name:"zh-tw/guide/schema-conversion/contract-fidelity.md"};function c(n,e,i,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="契約忠實度與演進" tabindex="-1">契約忠實度與演進 <a class="header-anchor" href="#契約忠實度與演進" aria-label="Permalink to &quot;契約忠實度與演進&quot;">​</a></h1><p>AsyncAPI 文件能成功解析，不代表訊息內容符合來源契約。測試分開記錄四層證據： TypeSpec 診斷、文件與 schema 解析、實際 payload <strong>與應用程式 headers</strong> 的接受結果， 以及舊 writer／新 reader 的序列化結果。Snapshot 或二進位解碼成功都不等於保留來源語意。</p><h2 id="驗證的-dialect" tabindex="-1">驗證的 dialect <a class="header-anchor" href="#驗證的-dialect" aria-label="Permalink to &quot;驗證的 dialect&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Lane</th><th>產生的契約</th><th>手寫契約</th><th>執行個體證據</th></tr></thead><tbody><tr><td>AsyncAPI 3.1／JSON Schema draft-07</td><td>下表支援的子集</td><td>AsyncAPI 與 draft-07 JSON/YAML 識別碼</td><td>獨立 Ajv + ajv-formats，保留遞迴參照</td></tr><tr><td>Avro 1.9.0</td><td>Preview record 轉換</td><td>Avro 物件 schema</td><td>avsc writer 編碼與獨立 reader resolver</td></tr><tr><td>Protobuf 3</td><td>Preview 自包含 proto3</td><td>手寫 proto3 文字</td><td>protobufjs 分別解析 writer/reader，明確指定 root</td></tr><tr><td>Protobuf 2</td><td>不產生 proto2</td><td>聚焦的手寫 proto2</td><td>required 與 default 行為，不宣稱支援產生 proto2</td></tr><tr><td>OpenAPI 3.0、RAML 1.0、其他識別碼</td><td>不宣稱轉換</td><td>識別碼與表示法透傳</td><td>不當成 draft-07 驗證；執行個體 helper 明確拒絕</td></tr></tbody></table><p>接受十四種 <code>schemaFormat</code> 識別碼，不等於實作十四種 payload 驗證器。 外層媒體型別與內部 schema 語法分別驗證。Native、產生的 Avro 與 proto3 都涵蓋 JSON 與 YAML 文件序列化。</p><h2 id="支援功能矩陣" tabindex="-1">支援功能矩陣 <a class="header-anchor" href="#支援功能矩陣" aria-label="Permalink to &quot;支援功能矩陣&quot;">​</a></h2><table tabindex="0"><thead><tr><th>IDs</th><th>Native JSON 見證值</th><th>二進位證據或明確限制</th></tr></thead><tbody><tr><td>F01</td><td>字串長度邊界、pattern、UUID、日期時間與 format profile</td><td>不支援的來源 constraints/formats 拒絕產生 artifact</td></tr><tr><td>F02</td><td>包含／排除邊界、小數、整數寬度、安全數值</td><td>支援的精確整數／bytes；更大值使用 codec 專用表示法</td></tr><tr><td>F03</td><td>陣列數量、元素、具名陣列、Record</td><td>支援陣列／map；不支援的限制或 indexed record 明確拒絕</td></tr><tr><td>F04</td><td>必填／選填、nullable、default 不注入</td><td>Avro null/default resolver；proto3 presence 不等於來源必填；明確來源 default 拒絕</td></tr><tr><td>F05</td><td>Epoch、duration、bytes 字母表、字串編碼、nullable 分支、default/example、scalar-chain constraints</td><td>不默默忽略來源 <code>@encode</code>，而是拒絕</td></tr><tr><td>F06</td><td>Literal/enum、anyOf/oneOf 重疊、空集合、discriminated envelope</td><td>Avro 分支限制、enum/default；protobuf 數字 enum 與不支援的 union</td></tr><tr><td>F07</td><td>多層繼承、繼承的必填欄位、遞迴／共用參照</td><td>遞迴 record/message；不支援的繼承拒絕；明確 protobuf root 與 descriptor parity</td></tr><tr><td>F08</td><td>自有、spread、lifting message 繼承的 header、獨立 headers model、編碼名稱</td><td>二進位 payload 旁保留 native headers；拒絕從 generated payload 提升欄位</td></tr><tr><td>F09</td><td>Dialect 編譯、錯誤 schema、跳脫／缺漏／循環參照、獨立 registry</td><td>手寫與產生的對照；不支援的 dialect 不計為已驗證</td></tr><tr><td>F10</td><td>Opaque scalar、visibility、數值／時間限制、extension 與 encoding 診斷</td><td>Metadata 拒絕的來源位置／數量；logical metadata 另行驗證</td></tr></tbody></table><p>從<strong>未標記</strong>的 base 繼承 <code>@header</code> 不會提升，既有 <code>inherited-header-ignored</code> 警告會讓欄位留在 payload。Base 本身是會提升 header 的 <code>@message</code> 時可以傳遞； spread 則把欄位變成 message 自有欄位。矩陣沒有改變這些規則。</p><p>新的 native 警告為 <code>unmapped-schema-scalar</code>、<code>unsupported-encoded-constraint</code>、 <code>unsupported-schema-keyword</code>、<code>schema-extension-overrides-contract</code>。 已知 extension 關鍵字值不合法時回報 <code>invalid-schema-extension</code> error。 Encoding 會改寫 scalar 的各層 <code>allOf</code>；不適用新 wire type 的 constraint 省略並警告， 不留下無意義的範圍或互相矛盾的型別，也不猜測數字轉字串範圍的 regex。 Nullable union 會依分支型別檢查，包含已知 scalar 參照與繼承的 encoding， 不修改共用 component。仍適用其他分支的限制會保留；真正未知的參照型別則保守處理。 作者新增的 <code>$ref</code> 若讓產生的同層驗證關鍵字失效，也會警告。 Enum 相等性不受物件鍵順序影響；schema 形式的 <code>dependencies</code> 也會檢查較新 draft 關鍵字。</p><h2 id="consumer-profile-與演進" tabindex="-1">Consumer profile 與演進 <a class="header-anchor" href="#consumer-profile-與演進" aria-label="Permalink to &quot;Consumer profile 與演進&quot;">​</a></h2><p>主要 JSON profile 為 <strong>open、assert formats</strong>：允許未知物件欄位、驗證已知 format、 拒絕未知 enum 值，並明確關閉 <code>coerceTypes</code>、<code>useDefaults</code>、<code>removeAdditional</code>。 驗證成功或失敗都不修改輸入。<strong>Closed</strong> profile 在明確物件路徑指定已知欄位， 不直接在 <code>allOf</code> 加上 <code>additionalProperties: false</code> 而誤判繼承欄位。 <strong>Format-annotation</strong> profile 則刻意不執行 format 限制。</p><p>Native／draft-07 oracle 忽略 <code>$ref</code> 同層的驗證關鍵字；要附加有效限制，請使用 <code>allOf</code> wrapper。Schema 位置的 OpenAPI <code>nullable</code> 會明確拒絕，不擴充 dialect。 Opaque annotation 只從不修改原始資料的編譯表示中移除，避免其中的 <code>$id</code> 註冊 schema 或解析真正的參照。真正的 schema 識別碼、遞迴參照與 <code>const</code>／<code>enum</code> 字面資料仍保留。 未提供的選填 headers 以空物件驗證；明確的 <code>null</code> 不會轉成空物件，會違反 object header schema。</p><p>未知驗證 keyword 或 format 會讓 helper 編譯失敗，除非明確標示 annotation-only。 <code>http-date</code> 的字面格式就是一項限制。數字／布林轉字串只證明 wire 表示為字串， 不證明標準字面文法。整數寬度是此 profile 的 assertion，不保證每個 JSON consumer 都會驗證。JSON 數值見證限於 JavaScript 安全精度，不宣稱證明完整 int64、uint64 或 decimal128。</p><p>每項獨立版本變更執行 P1→C1、P1→C2、P2→C1、P2→C2。Writer 必須先接受見證值 才序列化。E01–E10 涵蓋選填／必填新增、default、optional 變更、刪除、名稱／alias、 enum、constraint 縮緊／放寬、型別／encoding／tag 變更，以及 payload/header/envelope。 拒絕、保留原值、成功但有資料遺失或 default，分開判定。</p><p><strong>新增選填欄位也不是普遍安全。</strong> 舊 open 契約只有 <code>id: string</code> 時接受 <code>{ id: &quot;a&quot;, note: 42 }</code>；加入 <code>note?: string</code> 後就拒絕這個原本合法的訊息。 反向的新字串 <code>note</code> 可被舊 open consumer 接受，卻被 closed consumer 拒絕。 JSON 必填欄位的 default 不會自動補救舊訊息。</p><p>Avro 使用穩定 full name、<code>reader.createResolver(writer)</code>、<code>wrapUnions: false</code>。 未知 writer 欄位會略過；alias 有方向性；reader default 與 enum fallback 比對精確值， 不稱作原值保留。拒絕可能出現在建立 resolver，或讀取某個 union/enum 分支時。 產生的預設值會依完成的 Avro schema 圖遞迴檢查，包含具名 record、陣列、map， 以及每個巢狀 union 的第一個分支。外層預設值不會改排共用巢狀 union 的順序。 不合法或無限展開的預設值會回報 <code>tsp-avro/invalid-default</code> 並拒絕輸出。</p><p>Protobuf 分別建立 <code>keepCase: true</code> 的 root，明確選擇訊息。欄位值、自有欄位 presence、 未知數字 enum 與 tag 遺失各自 assertion。缺少 singular 欄位可能解碼成功卻違反來源 必填語意。舊 reader 解碼再編碼會遺失未知 tag；closed-enum 應用政策另外拒絕未知數字。 二進位名稱／tag 相容不等於 ProtoJSON 相容。 Protobuf scalar 的明確來源中繼資料會沿完整繼承鏈檢查，不在找到最近的 wire mapping 時停止；隱含的 wire mapping 仍受支援。</p><p>Avro logical type 名稱、單位、decimal precision/scale 與 fixed size 直接比對 emitted schema；沒有 custom logical adapter 的 avsc 不證明它們的語意。<code>local-timestamp-*</code> 不屬於宣告的 Avro 1.9.0，因此拒絕。</p><h2 id="保留訊息的版本化驗證" tabindex="-1">保留訊息的版本化驗證 <a class="header-anchor" href="#保留訊息的版本化驗證" aria-label="Permalink to &quot;保留訊息的版本化驗證&quot;">​</a></h2><p>Retention suite 透過<a href="./../versioning">版本化 adapter</a> 使用真正的 TypeSpec <code>@versioned</code> v1/v2/v3 檢視，不修改 JSON schema 來假裝版本變更。 接受結果判定之前，會先比對完整輸出集合 <code>asyncapi.1.0.json</code>、<code>asyncapi.2.0.json</code>、 <code>asyncapi.3.0.json</code>、各自的 <code>info.version</code>、AsyncAPI <strong>3.1.0</strong> 目標， 以及有效的 payload/header 欄位、必填集合、enum 成員、型別與限制邊界。</p><p>每個 JSON 見證值先通過自己的 <strong>producer snapshot</strong>，再由 <code>readJson</code> 序列化一次。 後續所有 consumer 重複使用保留下來的同一份值與序列化文字，不依 consumer 形狀重建、 改名、強制轉型、注入預設值或移除未知欄位。十個可個別歸因的 fixture 包含 34 筆 producer 訊息、204 個 consumer 結果（三個版本、兩種政策），其中 70 個預期拒絕。</p><table tabindex="0"><thead><tr><th>案例</th><th>真正的版本變更</th><th>保留訊息的證據</th></tr></thead><tbody><tr><td>R01</td><td>v2 新增選填欄位</td><td>只含已宣告欄位的 v1 訊息可繼續使用；舊契約合法的 <code>note: 42</code> 會與新的選填字串衝突。</td></tr><tr><td>R02</td><td>v2 新增有預設值的必填欄位</td><td>v1 省略欄位的訊息在 v2/v3 被拒絕，JSON 預設值不會補救。</td></tr><tr><td>R03a / R03b</td><td>選填變必填／必填變選填</td><td>分開的 fixture 呈現兩個方向，避免不同變更互相掩蓋。</td></tr><tr><td>R04</td><td>v2 移除必填欄位</td><td>寬容 reader 接受舊的額外欄位但不改寫資料；舊 reader 拒絕缺少該欄位的新訊息。</td></tr><tr><td>R05</td><td>v2 與 v3 分別改名</td><td>舊名、中間名稱與現名保持分離，佇列中的值不會自動遷移。</td></tr><tr><td>R06</td><td>v2 新增 enum 成員，v3 移除另一成員</td><td>v1 舊值可通過 v2 卻被 v3 拒絕；新成員也不被舊 consumer 接受。</td></tr><tr><td>R07</td><td>v2 縮緊整數範圍，v3 放寬</td><td>保留的端點值被中間版本拒絕；新放寬的值被舊 consumer 拒絕。</td></tr><tr><td>R08</td><td>字串改成整數，再改成整數或 null</td><td>不強制轉換數字文字，null 只被真正允許它的 snapshot 接受。</td></tr><tr><td>R09</td><td>v2 新增選填應用程式 header，v3 改成必填</td><td>Header 省略與未知名稱衝突會獨立失敗，不被未變的 payload 掩蓋。</td></tr></tbody></table><p>**寬容（tolerant）**只表示接受未知的 payload/header 欄位，不表示接受錯誤型別、 缺少必填欄位、未知 enum、無效 format 或違反邊界的值。 **嚴格（strict）**使用相同 schema 檢查，再加上明確的 consumer 已知欄位集合； 未宣告 headers 的版本不認得任何 header 名稱。所有 fixture producer 都使用 open profile，所以 open producer 的額外欄位見證值，即使交給同版本 strict consumer 也可能失敗。</p><p>另有部署控制分別輸出明確選取的 <code>&quot;1.0&quot;</code>、<code>&quot;2.0&quot;</code>、<code>&quot;3.0&quot;</code>。同一份保留中的 v1 <code>amount: 0</code> 被 v2 的下限 10 拒絕，再被 v3 的下限 0 接受。 這是假設原始訊息仍可取得，不宣稱 broker 在較早 consumer 嘗試交付後仍保留它。</p><p>有限的版本化 <strong>Avro 1.9</strong> 與 <strong>proto3</strong> 控制也只編碼 writer 位元組一次， 再以獨立建立的 v1/v2/v3 codec 讀取同一份位元組。Avro 比對精確的 reader 預設值 （<code>note: null</code>、<code>generation: 0</code>）、被略過的欄位，以及 v3 必填欄位沒有預設值時的 兩次 resolver 拒絕。v1 relay 會遺失 v3 內容，後來的預設值不會還原原值。 Protobuf 分別判定未知 tag 遺失與自有欄位缺席。v3 可成功解碼 v1 位元組，但 <strong>同一份 TypeSpec 來源</strong>的 native v3 檢視會拒絕缺少來源必填 <code>generation</code> 的訊息。 這些語意內容判定與保留位元組未改變是不同證據，不保證解碼再編碼後位元組相同。</p><p>較完整的<a href="https://github.com/cataggar/tsp-asyncapi/blob/main/test/integration/contract-binary-evolution.test.ts" target="_blank" rel="noreferrer">獨立二進位 writer/reader 矩陣</a> 仍涵蓋 alias、enum、型別/tag 變更及 reader/writer 限制；retention 控制不重複或 擴大那份能力宣告。測試把 producer schema 與 codec 身分和訊息一起保留 （Avro resolver 需要 writer schema），不模擬 schema registry 可用性、應用程式遷移、 broker 儲存或交付操作。</p><h2 id="範圍與執行" tabindex="-1">範圍與執行 <a class="header-anchor" href="#範圍與執行" aria-label="Permalink to &quot;範圍與執行&quot;">​</a></h2><p>既有 Vitest runner 自動探索 <code>contract-fidelity</code>、<code>contract-native-diagnostics</code>、 <code>contract-encoded-union-references</code>、<code>contract-validator-draft07</code>、<code>contract-evolution</code>、 <code>contract-binary-fidelity</code>、<code>contract-binary-evolution</code>、 <code>contract-versioned-retention</code>、<code>contract-versioned-binary-retention</code>。 資料列在 <code>test/fixtures/contract-fidelity</code>，二進位 pair 的預期值在各 suite。 預期拒絕是一般 assertion，不是 skip。產生的有限整數見證使用 seed <code>3107</code>。</p><p>使用 Node 24 與 workspace 指定的 pnpm；鎖定的 TypeSpec compiler 需要 Node 22 以上。 先 build 再跑選定的 contract suite。驗證器僅為 test utility，不加入 emitter runtime。</p><p>有限見證是指定 profile 的反例或證據，<strong>不是</strong> schema 語言包含關係、所有 client 或所有歷史 producer 的相容性證明。獨立編譯的新舊來源與真正版本化的 retention 矩陣提供不同證據，都不保證每份佇列訊息或每種保留視窗的相容性。</p><p>AsyncAPI 使用 draft-07、nullable union 與自己的 discriminator，不是 OpenAPI 3.0 <code>nullable</code> 或 HTTP request/response visibility 投影。部分 lifecycle visibility 不會 選擇 send/receive shape。JSON encoded name 依媒體型別區分，不是二進位 alias。 應用程式 headers 不是 broker-native metadata；測試不證明交付、排序、TTL、 settlement、retry、exactly-once processing、deduplication、idempotency 或業務語意。</p>',31)])])}const m=t(a,[["render",c]]);export{h as __pageData,m as default};
